h,w=23,17
g=[[3]*w for _ in range(h)]
for c in range(13,17): g[0][c]=6
for c in range(6,10): g[22][c]=6
for r in range(1,22):
    for c in range(14,17): g[r][c]=1
# bottom-to-top propagation, shrink stripe at each encountered marker
markers=[(5,7),(18,9),(20,8)]
active={7,8,9}
for r in range(21,-1,-1):
    for c in active:
        g[r][c]=1
    for rr,cc in markers:
        if rr==r:
            g[r][cc]=4
            active.remove(cc)
print('\n'.join(' '.join(map(str,row)) for row in g))
